import React from "react";
import { TouchableOpacity, Text } from "react-native";

const MockCloseButton = ({ onPress, testID, ...props }) => (
  <TouchableOpacity onPress={onPress} testID={testID} {...props}>
    <Text>×</Text>
  </TouchableOpacity>
);

MockCloseButton.displayName = "MockCloseButton";

export default MockCloseButton;
